// Map a Gmail message to the LeadPilot reply webhook.
// outreach_id is omitted: the backend resolves the outreach
// by matching From to the contact's business email.
const m = $input.first().json;
const headers = {};
for (const h of (m.payload?.headers || [])) headers[h.name.toLowerCase()] = h.value;
return [{ json: {
  event_type: 'reply',
  from_address: (headers['from'] || '').replace(/.*<(.+)>.*/, '$1'),
  subject: headers['subject'] || '',
  body: m.snippet || ''
} }];
